/* btr-trace */
(function(){
  var SEL='button:not(.bimute),.ai .tech,.ps .tab,[data-go]';
  var app=document.getElementById('app');
  function add(b){
    if(b.__btr||b.closest('.btr'))return;
    b.__btr=1;
    if(getComputedStyle(b).position==='static')b.style.position='relative';
    var s=document.createElement('span');s.className='btr off';s.setAttribute('aria-hidden','true');
    s.appendChild(document.createElement('i'));
    var t=18+Math.random()*14;
    s.style.setProperty('--t',t.toFixed(1)+'s');
    s.style.setProperty('--dl',(-Math.random()*t).toFixed(1)+'s');
    s.style.setProperty('--a0',Math.round(Math.random()*360)+'deg');
    s.style.setProperty('--dir',Math.random()<.5?'normal':'reverse');
    s.style.setProperty('--o',(.58+Math.random()*.12).toFixed(2));
    if(getComputedStyle(b).borderRadius==='0px'&&!b.hasAttribute('data-go')){s.style.borderRadius='16px';s.style.inset='2px';}
    b.appendChild(s);
  }
  function scan(){var n=0;document.querySelectorAll(SEL).forEach(function(b){if(!b.__btr||!b.querySelector(':scope>.btr')){b.__btr=0;add(b);n++}});return n}
  function vis(){
    document.querySelectorAll('.btr').forEach(function(s){
      var b=s.parentNode,on=b.checkVisibility?b.checkVisibility({opacityProperty:true,visibilityProperty:true}):!!b.offsetParent;
      if(on&&!s.__d){var w=b.offsetWidth,h=b.offsetHeight;if(w&&h){s.style.setProperty('--d',Math.ceil(Math.hypot(w,h)+4)+'px');s.__d=1}}
      s.classList.toggle('off',!on);
    });
  }
  var idle=window.requestIdleCallback||function(f){return setTimeout(f,1)};
  var vt=[];function later(){vt.forEach(clearTimeout);vt=[900,2300,4300,6800].map(function(d){return setTimeout(function(){idle(vis,{timeout:400})},d)})}
  var mt=null;
  function go(){
    scan();later();
    new MutationObserver(later).observe(app,{attributes:true,attributeFilter:['data-screen']});
    new MutationObserver(function(){if(mt)return;mt=setTimeout(function(){mt=null;idle(function(){if(scan())setTimeout(function(){idle(vis,{timeout:600})},300)},{timeout:600})},500)}).observe(app,{childList:true,subtree:true});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',go);else go();
})();

