/* gl-pulse */
(function(){
  var app=document.getElementById('app');var t=document.querySelector('.tile[data-go="glance"]');
  if(!t||!t.animate)return;
  t.querySelectorAll('video').forEach(function(v){try{v.pause();v.removeAttribute('src');v.load()}catch(e){}v.remove()});t.classList.remove('has-v');
  var c=document.createElement('span');c.className='gpl';c.setAttribute('aria-hidden','true');
  var L={};['gpp','gsc','gsl','gsr'].forEach(function(k){var e=document.createElement('i');e.className=k;c.appendChild(e);L[k]=e});
  var ifx=t.querySelector('.ifx');t.insertBefore(c,ifx?ifx.nextSibling:t.firstChild);
})();
